class core {	
	public static function init(){
		$actionName = array_key_exists('m', $_GET)?$_GET['m']:'index';
		$model 		= new oss();
		$methods 	= get_class_methods($model);

		if(in_array($actionName, $methods)){
			call_user_func_array(array($model, $actionName), array());	
		}else{
			self::error('Error!');
		}		
	}	
	public static function error($msg){
		echo $msg;exit();
	}
}

core::init();

class oss {
	protected $sessionName;
	protected $configInfos;
	protected $dbPath;
	protected $post;
	protected $packTypes;
	
	public function __construct(){		
	   $this->sessionName = _PREV;
	   if(!is_dir(ATTACHMENT_ROOT)){mkdirs(ATTACHMENT_ROOT);}
	   
	   $this->dbPath = search_file(_PREV,'xml');
	   
	   if(empty($this->dbPath)){
		   $this->dbPath      = _PREV.generate_code(6).'.xml';
		   $this->configInfos = createDb($this->dbPath );
	   }else{
		   $this->configInfos = xml2array(file_read($this->dbPath));
	   }
	   $this->post = strtolower($_SERVER['REQUEST_METHOD']) === 'post' ? true : false;
	   $this->packTypes = array('WGT资源包','Android包','IOS包');
    }
	
	public function delpack(){
		if($this->checkLogin()){
			if($this->post){
				$pack_id  = $_POST['pack_id'];
				$packages = $this->configInfos['packages'];
				if(array_key_exists($pack_id,$packages)){
					unset($packages[$pack_id]);
					$this->configInfos['packages'] = $packages;
					$this->save();
					showJson(1,'删除成功');
				}else{
					showJson(1,'删除失败');
				}				
			}
		}
	}
    public function version(){
		header('Content-type:text/json');

		$clientType = isset($_POST['client_type'])?intval($_POST['client_type']):0;
		$curVersion = isset($_POST['current_version'])?intval($_POST['current_version']):0;
		
		$packages 	= $this->configInfos['packages'];
		$pack_times = array_column($packages,'pack_time');
		array_multisort($pack_times,SORT_DESC,$packages);
		
		$NewVersion = array();	
		foreach($packages as $pack){
			if(empty($NewVersion) && ($pack['pack_type']==$clientType || $pack['pack_type']==0) && intval($pack['pack_version'])>$curVersion){
				$NewVersion = $pack;
			}
		}
		if(empty($NewVersion)){
			showJson(0,'当前已是最新版本');
		}else{
			showJson(200,'',$NewVersion);
		}
    }


	public function fetchs(){
		header('Content-type:text/json');
		if($this->checkLogin()){
			$packages 	= $this->configInfos['packages'];
			//对数组按照时间戳进行排序
			$pack_times = array_column($packages,'pack_time');
			array_multisort($pack_times,SORT_DESC,$packages);
			
			$page   	= isset($_GET['page']) && $_GET['page']!=''?intval($_GET['page']):1;
			$limit  	= isset($_GET['limit']) && $_GET['limit']!=''?intval($_GET['limit']):10;
			$ret_array	= array();
			$ret_index	= 0;
			foreach($packages as $k => $v){
				if($ret_index>=(($page-1)*$limit) && $ret_index<=($page*$limit)){
					$v['pack_id'] 	= $k;
					$v['pack_type'] = $this->packTypes[$v['pack_type']];
					$v['pack_time'] = date('Y-m-d H:i:s',$v['pack_time']);
					array_push($ret_array,$v);
				}
				$ret_index++;
			}
			echo json_encode(array('code'=>0,'msg'=>'','count'=>count($packages),'data'=>$ret_array));
		}
	}
	
	public function login(){
		if($this->post){
			$password = md5($_POST['password']);
			if(md5(_PASS)===$password){
				$_SESSION[$this->sessionName] = $password;
				showJson(1,'登录成功');
			}else{
				showJson(0,'登录失败');
			}
		}else{
			showLogin();
		}	
	}
	
	public function upload(){
		if($this->checkLogin()){
			$FileName = $this->uploadFile('file');
			showJson(1,'成功',array('filepath'=>$FileName));
		}	
	}
	
	public function update(){
		if($this->checkLogin()){
			if($this->post){
				$package = array(
					'pack_type' 	=> $_POST['pack_type'],
					'pack_version'  => $_POST['pack_version'],
					'pack_file' 	=> $_POST['pack_file'],
					'pack_url'      => $_POST['pack_url'],
					'pack_info'     => $_POST['pack_info'],
					'pack_time'		=> time()
				);
				if($_POST['pack_type']==2 && !empty($_POST['pack_file'])){
					$package['pack_file'] = createPlist($_POST['pack_file'],$this->configInfos['config_logo'],$_POST['pack_version'],$this->configInfos['config_name'],$this->configInfos['config_ios_packname']);	
				}			
				$nodeName = 'P'.date('YmdHis',time());			
				$this->configInfos['packages'][$nodeName]=$package;	
				$this->save();
				showJson(1);
			}
		}
	}
	
	public function basic(){
		if($this->checkLogin()){
			showJson(1,'',array('config'=>$this->configInfos));			
		}	
	}
	
	public function setting(){
		if($this->checkLogin()){
			$this->configInfos['config_name'] 				= $_POST['config_name'];
			$this->configInfos['config_logo'] 				= $_POST['config_logo'];
			$this->configInfos['config_ios_packname'] 		= $_POST['config_ios_packname'];
			$this->configInfos['config_android_packname'] 	= $_POST['config_android_packname'];
			$this->configInfos['config_host_name'] 			= $_POST['config_host_name'];
			$this->configInfos['config_download_url'] 		= $_POST['config_download_url'];
			$this->save();
			showJson(1);
		}	
	}	
	
	public function index(){
		if($this->checkLogin()){
			showIndex();
		}else{
			$download 	= array('logo'=>$this->configInfos['config_logo'],'name'=>$this->configInfos['config_name'],'android'=>'','ios'=>'');
			$packages 	= $this->configInfos['packages'];
			$pack_times = array_column($packages,'pack_time');
			array_multisort($pack_times,SORT_DESC,$packages);
			foreach($packages as $pack){
				if(empty($download['android']) && $pack['pack_type']==1){// 安卓
					$download['android'] = empty($pack['pack_url'])?$pack['pack_file']:$pack['pack_url'];
				}
				if(empty($download['ios']) && $pack['pack_type']==2){// 安卓
					$download['ios'] = empty($pack['pack_url'])?'itms-services://?action=download-manifest&url='.urlencode($pack['pack_file']):$pack['pack_url'];
				}
			}		
			showDownload($download['logo'],$download['name'],$download['android'],$download['ios']);
		}
	}
	private function save(){
		file_write($this->dbPath,array2xml($this->configInfos));
	}
	private function uploadFile($FielName){
		$allowExt = array('png','gif', 'jpg', 'bmp', 'webp', 'jpeg', 'apk', 'ipa','wgt','zip', 'rar');
		if($_FILES[$FielName]["error"] != 0) {
			showJson(0,'发生错误');
		}else{
			$fileExt = strtolower(substr(strrchr($_FILES[$FielName]["name"], '.'), 1));
			if(!in_array(strtolower($fileExt),$allowExt)){
				showJson(0,'不允许的格式');	
			}
			$host = 'https://';
			$img_allowExt = array('png','gif', 'jpg', 'bmp', 'webp', 'jpeg','apk','wgt','zip', 'rar');
			if(in_array(strtolower($fileExt),$img_allowExt)){
				$host = $_SERVER['REQUEST_SCHEME'].'://';
			}
			$FolderName  = date('Ymd',time());
			$FilePath 	 = ATTACHMENT . '/' . $FolderName;
			if(!is_dir($FilePath)){mkdirs($FilePath);}
			$NewFielName = getMillisecond(). '.' . $fileExt;
			move_uploaded_file($_FILES[$FielName]["tmp_name"], $FilePath.'/'.$NewFielName);
			$FileUri = $host.$_SERVER['HTTP_HOST'].str_replace($_SERVER['DOCUMENT_ROOT'],'',IA_ROOT).'/'.ATTACHMENT . '/' . $FolderName .'/'.$NewFielName;
			return $FileUri;	
		}
	}	
	
	
	private function checkLogin(){
		$loginUri = '?m=login';
		if(isset($_SESSION[$this->sessionName]) && !empty($_SESSION[$this->sessionName])){
			if(md5(_PASS) === $_SESSION[$this->sessionName]){
				return 1;
			}else{
				return 0;
			}
		}  
	}
	
}
// 公共函数
function showJson($errno,$message='',$data=array()){
	header('Content-type:text/json');
	header('Access-Control-Allow-Origin: *');
	echo json_encode(array('code' => $errno,'message' => $message,'result'=>$data));exit();
}


function createPlist($AppFile,$AppLogo,$AppVersion,$AppName,$AppBundle){
	$plist_str='';
	$plist_str.='<?xml version="1.0" encoding="UTF-8"?>';
	$plist_str.='<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">';
	$plist_str.='<plist version="1.0">';
	$plist_str.='<dict>';
	$plist_str.='	<key>items</key>';
	$plist_str.='	<array>';
	$plist_str.='		<dict>';
	$plist_str.='			<key>assets</key>';
	$plist_str.='			<array>';
	$plist_str.='				<dict>';
	$plist_str.='					<key>kind</key>';
	$plist_str.='					<string>software-package</string>';
	$plist_str.='					<key>url</key>';
	$plist_str.='					<string>'.$AppFile.'</string>';
	$plist_str.='				</dict>';
	$plist_str.='				<dict>';
	$plist_str.='					<key>kind</key>';
	$plist_str.='					<string>full-size-image</string>';
	$plist_str.='					<key>needs-shine</key>';
	$plist_str.='					<true/>';
	$plist_str.='					<key>url</key>';
	$plist_str.='					<string>'.$AppLogo.'</string>';
	$plist_str.='				</dict>';
	$plist_str.='				<dict>';
	$plist_str.='					<key>kind</key>';
	$plist_str.='					<string>display-image</string>';
	$plist_str.='					<key>needs-shine</key>';
	$plist_str.='					<true/>';
	$plist_str.='					<key>url</key>';
	$plist_str.='					<string>'.$AppLogo.'</string>';
	$plist_str.='				</dict>';
	$plist_str.='			</array>';
	$plist_str.='			<key>metadata</key>';
	$plist_str.='			<dict>';
	$plist_str.='				<key>bundle-identifier</key>';
	$plist_str.='				<string>'.$AppBundle.'</string>';
	$plist_str.='				<key>bundle-version</key>';
	$plist_str.='				<string>'.$AppVersion.'</string>';
	$plist_str.='				<key>kind</key>';
	$plist_str.='				<string>software</string>';
	$plist_str.='				<key>subtitle</key>';
	$plist_str.='				<string>install app</string>';
	$plist_str.='				<key>title</key>';
	$plist_str.='				<string>'.$AppName.'</string>';
	$plist_str.='			</dict>';
	$plist_str.='		</dict>';
	$plist_str.='	</array>';
	$plist_str.='</dict>';
	$plist_str.='</plist>';


	$FolderName  = date('Ymd',time());
	$FilePath 	 = ATTACHMENT . '/' . $FolderName;
	if(!is_dir($FilePath)){mkdirs($FilePath);}
	$NewFielName = getMillisecond(). '.plist';
	
	file_put_contents($FilePath.'/'.$NewFielName,$plist_str);

	$FileUri = 'https://'.$_SERVER['HTTP_HOST'].str_replace($_SERVER['DOCUMENT_ROOT'],'',IA_ROOT).'/'.ATTACHMENT . '/' . $FolderName .'/'.$NewFielName;



	
	return  $FileUri;  

}

