			function checkUpdate() {
				var client_type = window.plus.os.name == "Android" ? 1 : 2;
				var current_version = 0;
				var apiurl = "http://www.baidu.com/index.php";

				plus.runtime.getProperty(plus.runtime.appid,
				function(inf) {
					current_version = inf.version;
					$.post(apiurl + \'?m=version\', {
						current_version: current_version,
						client_type: client_type
					},
					function(ret) {
						if (ret.code == 200) {
							var result = ret.result;
							plus.nativeUI.confirm("系统检测到更新,是否更新",
							function(e) {
								if (e.index == 0) {
									if (result.pack_url != "") { // pack_url 不为空的时候 直接跳转
										plus.runtime.openURL(result.pack_url);
									}

									if (result.pack_type == 2) { //IOS更新 直接打开下载页面
										plus.runtime.openURL(apiurl);
									} else { // 安卓或WGT更新，下载文件并执行安装
										install(result.pack_file);
									}
								}
							})
						} else {
							console.log(\'无更新\');
						}
					},
					\'json\');
				});
			}
			function install(fileUri) {
				plus.downloader.createDownload(fileUri, {
					filename: "_doc/update/"
				},
				function(d, status) {
					if (status == 200) {
						plus.runtime.install(d.filename, {
							force: true
						},
						function() {
							plus.nativeUI.closeWaiting();
							plus.nativeUI.alert("应用资源更新完成！",
							function() {
								plus.runtime.restart();
							});
						},
						function(e) {
							plus.nativeUI.closeWaiting();
							console.log("安装文件失败[" + e.code + "]：" + e.message);
						});
					} else {
						console.log("下载失败！");
					}
					plus.nativeUI.closeWaiting();
				}).start();
			}
		</pre>
	
