function createDb($dbName){
	$xml = array(
		'config_logo'				=>'1',
		'config_name'				=>'1',
		'config_ios_packname'		=>'1',
		'config_android_packname'	=>'1',
		'config_download_url'		=>'1',
		'config_host_name'			=>'1',
		'packages'=>array()
	);
	file_write($dbName,array2xml($xml));
	return $xml;
}

function search_file($key,$ext){		
	$files = glob(ATTACHMENT_ROOT . '/*');
	foreach($files as $file){
		$fileInfo = pathinfo($file);
		if(array_key_exists('extension',$fileInfo) && $fileInfo['extension']==$ext){
			if(strexists($fileInfo['filename'],$key)){
				return $fileInfo['basename'];
			}	
		}
	}
}

function getMillisecond(){
	list($t1, $t2) = explode(' ', microtime());
	return (float)sprintf('%.0f', (floatval($t1) + floatval($t2)) * 1000);
}

function generate_code($length){
	return rand(pow(10, ($length - 1)), pow(10, $length) - 1);
}

function strexists($string, $find) {
	return !(false === strpos($string, $find));
}

function array2xml($arr, $level = 1) {
	$s = 1 == $level ? '<xml>' : '';
	foreach ($arr as $tagname => $value) {
		if (!is_array($value)) {
			$s .= "<{$tagname}>" . (!is_numeric($value) ? '<![CDATA[' : '') . $value . (!is_numeric($value) ? ']]>' : '') . "</{$tagname}>";
		} else {
			$s .= "<{$tagname}>" . array2xml($value, $level + 1) . "</{$tagname}>";
		}
	}
	$s = preg_replace("/([\x01-\x08\x0b-\x0c\x0e-\x1f])+/", ' ', $s);
	return 1 == $level ? $s . '</xml>' : $s;
}

function xml2array($xml) {
	if (empty($xml)) {
		return array();
	}
	$result = array();
	$xmlobj = isimplexml_load_string($xml, 'SimpleXMLElement', LIBXML_NOCDATA);
	if ($xmlobj instanceof SimpleXMLElement) {
		$result = json_decode(json_encode($xmlobj), true);
		if (is_array($result)) {
			return $result;
		} else {
			return '';
		}
	} else {
		return $result;
	}
}

function mkdirs($path) {
	if (!is_dir($path)) {
		mkdirs(dirname($path));
		mkdir($path);
	}
	return is_dir($path);
}
function file_write($filename, $data) {
	$filename = ATTACHMENT_ROOT . '/' . $filename;
	mkdirs(dirname($filename));
	file_put_contents($filename, $data);
	return is_file($filename);
}
function file_read($filename) {
	$filename = ATTACHMENT_ROOT . '/' . $filename;
	if (!is_file($filename)) {
		return false;
	}
	return file_get_contents($filename);
}
function isimplexml_load_string($string, $class_name = 'SimpleXMLElement', $options = 0, $ns = '', $is_prefix = false) {
	libxml_disable_entity_loader(true);
	if (preg_match('/(\<\!DOCTYPE|\<\!ENTITY)/i', $string)) {
		return false;
	}
	$string = preg_replace('/[\\x00-\\x08\\x0b-\\x0c\\x0e-\\x1f\\x7f]/', '', $string); 	return simplexml_load_string($string, $class_name, $options, $ns, $is_prefix);
}
